def longestHappyLength(a, b, c):
    cnt = [a, b, c]
    last = -1
    run = 0
    total = 0
    while True:
        order = sorted((0, 1, 2), key=lambda i: -cnt[i])
        picked = -1
        for i in order:
            if cnt[i] == 0:
                break
            if i == last and run == 2:
                continue
            picked = i
            break
        if picked < 0:
            return total
        cnt[picked] -= 1
        total += 1
        if picked == last:
            run += 1
        else:
            last = picked
            run = 1
